package com.innovatus.studentrecords.service; import com.innovatus.studentrecords.dao.UserDAO; import com.innovatus.studentrecords.model.User; import com.innovatus.studentrecords.utils.*; import java.sql.*; import java.util.*;
public class AuthService {private final UserDAO dao=new UserDAO(); public User signup(String n,String e,String p,String c,String d)throws Exception{if(Validator.blank(n)||Validator.blank(e)||Validator.blank(p)||Validator.blank(d))throw new IllegalArgumentException("All fields are required.");if(!Validator.email(e))throw new IllegalArgumentException("Enter a valid email address.");if(!Validator.password(p))throw new IllegalArgumentException("Password must be at least 8 characters.");if(!p.equals(c))throw new IllegalArgumentException("Passwords do not match.");if(dao.findByUsername(n).isPresent()||dao.findByEmail(e).isPresent())throw new IllegalArgumentException("Username or email already exists.");return dao.create(n.trim(),e.trim(),PasswordUtil.hash(p),d.trim());} public User login(String n,String p)throws Exception{if(Validator.blank(n)||Validator.blank(p))throw new IllegalArgumentException("Username and password are required.");Optional<User> u=dao.findByUsername(n.trim());if(u.isEmpty())throw new IllegalArgumentException("Invalid username.");if(!u.get().passwordHash().equals(PasswordUtil.hash(p)))throw new IllegalArgumentException("Invalid password.");return u.get();} public void reset(String e,String p)throws Exception{if(!Validator.password(p))throw new IllegalArgumentException("Password must be at least 8 characters.");dao.updatePassword(e,PasswordUtil.hash(p));}}
